      display: none;
    }

    input[aria-invalid="true"] {
      border-color: var(--danger);
      box-shadow: 0 0 0 4px rgba(185, 28, 28, 0.12);
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-strong) 100%);
