<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="support-layout" aria-labelledby="support-heading">
      <div class="hero">
        <p class="eyebrow">Support</p>
        <h1 id="support-heading">Talk to our support team.</h1>
        <p>
          Share your details and we will follow up with help for billing, account access,
          or product questions. Required fields are marked with <span class="required-indicator">*</span>.
        </p>
        <ul class="hero-points" aria-label="Support benefits">
          <li>
            Fast response
            <span>Get a reply from a specialist who can route your request quickly.</span>
          </li>
          <li>
            Clear follow-up
            <span>We use your contact details only to respond to this support request.</span>
          </li>
        </ul>
      </div>

      <div class="form-card">
        <h2>Contact support</h2>
        <p>Complete the form below and submit your request.</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-required="true"
              aria-describedby="full-name-error"
              placeholder="Jordan Lee"
            >
            <p class="error-text" id="full-name-error" hidden>Please enter your full name.</p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-required="true"
              aria-describedby="email-error"
              placeholder="you@example.com"
            >
            <p class="error-text" id="email-error" hidden>Please enter a valid email address.</p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-helper phone-error"
              placeholder="(555) 123-4567"
            >
            <p class="helper-text" id="phone-helper">Optional. Use a format like (555) 123-4567 or +1 555 123 4567.</p>
            <p class="error-text" id="phone-error" hidden>Please enter a valid phone number using digits and common separators.</p>
          </div>

          <div class="actions">
            <button type="submit">Submit request</button>
            <p class="status-text" id="form-status" aria-live="polite" hidden>Your support request is ready to send.</p>
          </div>
        </form>
      </div>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const formStatus = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          return value.trim().length > 0;
        },
        message: 'Please enter your full name.'
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('email-error'),
        validate(value) {
          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
        },
        message: 'Please enter a valid email address.'
      },
      phone: {
        input: document.getElementById('phone'),
        error: document.getElementById('phone-error'),
        validate(value) {
          const trimmed = value.trim();
          return trimmed === '' || /^[+]?[0-9()\-\s.]{7,20}$/.test(trimmed);
        },
        message: 'Please enter a valid phone number using digits and common separators.'
      }
    };

    function setFieldValidity(field, isValid) {
      field.input.setAttribute('aria-invalid', String(!isValid));
      field.error.hidden = isValid;
      field.error.textContent = field.message;
    }

    function validateField(fieldName) {
      const field = fields[fieldName];
      const isValid = field.validate(field.input.value);
      setFieldValidity(field, isValid);
      return isValid;
    }

    Object.keys(fields).forEach((fieldName) => {
      const field = fields[fieldName];
      field.input.addEventListener('blur', () => {
        validateField(fieldName);
      });

      field.input.addEventListener('input', () => {
        if (!field.error.hidden) {
          validateField(fieldName);
        }

        formStatus.hidden = true;
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const validationOrder = ['fullName', 'email', 'phone'];
      const invalidField = validationOrder.find((fieldName) => !validateField(fieldName));

      if (invalidField) {
        formStatus.hidden = true;
        fields[invalidField].input.focus();
        return;
      }

      formStatus.hidden = false;
      form.reset();

      Object.values(fields).forEach((field) => {
        field.input.setAttribute('aria-invalid', 'false');
        field.error.hidden = true;
      });
    });
  </script>
</body>
</html>
